package com.example.activite.web.controller;
import com.example.activite.domain.Client; import com.example.activite.service.IClientService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.Parameter; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/clients") @RequiredArgsConstructor @Tag(name="Clients",description="Gestion des clients") public class ClientController { private final IClientService clientService;
@GetMapping @Operation(summary="Lister les clients") @ApiResponse(responseCode="200",description="Liste retournée") public List<Client> findAll(){return clientService.findAll();}
@GetMapping("/{id}") @Operation(summary="Consulter un client") @ApiResponses({@ApiResponse(responseCode="200",description="Client trouvé"),@ApiResponse(responseCode="404",description="Client introuvable")}) public Client findById(@Parameter(description="Identifiant du client") @PathVariable Long id){return clientService.findById(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Créer un client") @ApiResponses({@ApiResponse(responseCode="201",description="Client créé"),@ApiResponse(responseCode="400",description="Données invalides")}) public Client create(@RequestBody Client c){return clientService.create(c);}
@PutMapping("/{id}") @Operation(summary="Modifier un client") @ApiResponses({@ApiResponse(responseCode="200",description="Client modifié"),@ApiResponse(responseCode="400",description="Données invalides"),@ApiResponse(responseCode="404",description="Client introuvable")}) public Client update(@PathVariable Long id,@RequestBody Client c){return clientService.update(id,c);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Supprimer un client") @ApiResponses({@ApiResponse(responseCode="204",description="Client supprimé"),@ApiResponse(responseCode="404",description="Client introuvable")}) public void deleteById(@PathVariable Long id){clientService.deleteById(id);}}
